add('simplifier', 'SpecHygieneW1', f"""Validate this wave's spec hygiene: read {L}/.ufo/waves/round-34/make-spec-w1.py and the rendered {L}/.ufo/waves/round-34/w1-dispatch.json. Check: distinct ids and prompts; roles only from the allowed 10 (no planner); attack share (reviewer+critic+mutation-tester) >= 25 %; every path absolute; every scratch path under {SCR}/<item>/; every delivery file under {W}/ and unique; no two executors told to change the same lane file (executors here are read-only — verify no item asks a seat to edit the lane); every item names what it builds or attacks; the context carries the pacman guard and the tooling authorization. Report defects with item ids. Deliver findings in your report.""")

c = collections.Counter(i['role'] for i in ITEMS)
n = len(ITEMS)
assert len({i['item'] for i in ITEMS}) == n and len({i['prompt'] for i in ITEMS}) == n
attack = sum(c[r] for r in ('reviewer', 'critic', 'mutation-tester'))
assert 32 <= n <= 64 and attack * 4 >= n, (n, dict(c), attack)
spec = {'wave': 'souji-r34-w1', 'reportDir': '.ufo/waves/round-34/w1', 'maxLanes': 64, 'context': CONTEXT, 'items': ITEMS}
json.dump(spec, open(L + '/.ufo/waves/round-34/w1-spec.json', 'w'), ensure_ascii=False, indent=1)
print(n, dict(c), 'attack', attack)
